124	void Leader::RemoveBorderRouter(uint16_t aRloc16, MatchMode aMatchMode)
125	{
126	    bool rlocIn     = false;
127	    bool rlocStable = false;
128	
129	    RlocLookup(aRloc16, rlocIn, rlocStable, mTlvs, mLength, aMatchMode);
130	    VerifyOrExit(rlocIn);
131	    RemoveRloc(aRloc16, aMatchMode);
132	
133	    mVersion++;
134	
135	    if (rlocStable)
136	    {
137	        mStableVersion++;
138	    }
139	
140	    Get<Notifier>().Signal(OT_CHANGED_THREAD_NETDATA);
141	
142	exit:
143	    return;
144	}
