291	void Leader::HandleCommissioningGet(Coap::Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
292	{
293	    MeshCoP::Tlv tlv;
294	    uint16_t     offset = aMessage.GetOffset();
295	    uint8_t      tlvs[NetworkData::kMaxSize];
296	    uint8_t      length = 0;
297	
298	    while (offset < aMessage.GetLength())
299	    {
300	        aMessage.Read(offset, sizeof(tlv), &tlv);
301	
302	        if (tlv.GetType() == MeshCoP::Tlv::kGet)
303	        {
304	            length = tlv.GetLength();
305	            aMessage.Read(offset + sizeof(MeshCoP::Tlv), length, tlvs);
306	            break;
307	        }
308	
309	        offset += sizeof(tlv) + tlv.GetLength();
310	    }
311	
312	    SendCommissioningGetResponse(aMessage, aMessageInfo, tlvs, length);
313	}
314	
315	void Leader::SendCommissioningGetResponse(const Coap::Message &   aRequest,
316	                                          const Ip6::MessageInfo &aMessageInfo,
317	                                          const uint8_t *         aTlvs,
318	                                          uint8_t                 aLength)
319	{
320	    otError        error = OT_ERROR_NONE;
321	    Coap::Message *message;
322	    uint8_t        index;
323	    uint8_t *      data   = NULL;
324	    uint8_t        length = 0;
325	
326	    VerifyOrExit((message = MeshCoP::NewMeshCoPMessage(Get<Coap::Coap>())) != NULL, error = OT_ERROR_NO_BUFS);
327	
328	    message->SetDefaultResponseHeader(aRequest);
329	    message->SetPayloadMarker();
330	
331	    for (NetworkDataTlv *cur                                            = reinterpret_cast<NetworkDataTlv *>(mTlvs);
332	         cur < reinterpret_cast<NetworkDataTlv *>(mTlvs + mLength); cur = cur->GetNext())
333	    {
334	        if (cur->GetType() == NetworkDataTlv::kTypeCommissioningData)
335	        {
336	            data   = cur->GetValue();
337	            length = cur->GetLength();
338	            break;
339	        }
340	    }
341	
342	    VerifyOrExit(data && length, error = OT_ERROR_DROP);
343	
344	    if (aLength == 0)
345	    {
346	        SuccessOrExit(error = message->Append(data, length));
347	    }
348	    else
349	    {
350	        for (index = 0; index < aLength; index++)
351	        {
352	            for (MeshCoP::Tlv *cur                                          = reinterpret_cast<MeshCoP::Tlv *>(data);
353	                 cur < reinterpret_cast<MeshCoP::Tlv *>(data + length); cur = cur->GetNext())
354	            {
355	                if (cur->GetType() == aTlvs[index])
356	                {
357	                    SuccessOrExit(error = message->AppendTlv(*cur));
358	                    break;
359	                }
360	            }
361	        }
362	    }
363	
364	    if (message->GetLength() == message->GetOffset())
365	    {
366	        // no payload, remove coap payload marker
367	        message->SetLength(message->GetLength() - 1);
368	    }
369	
370	    SuccessOrExit(error = Get<Coap::Coap>().SendMessage(*message, aMessageInfo));
371	
372	    otLogInfoMeshCoP("sent commissioning dataset get response");
373	
374	exit:
375	
376	    if (error != OT_ERROR_NONE && message != NULL)
377	    {
378	        message->Free();
379	    }
380	}
