411	bool Leader::RlocMatch(uint16_t aFirstRloc16, uint16_t aSecondRloc16, MatchMode aMatchMode)
412	{
413	    bool matched = false;
414	
415	    switch (aMatchMode)
416	    {
417	    case kMatchModeRloc16:
418	        matched = (aFirstRloc16 == aSecondRloc16);
419	        break;
420	
421	    case kMatchModeRouterId:
422	        matched = Mle::Mle::RouterIdMatch(aFirstRloc16, aSecondRloc16);
423	        break;
424	    }
425	
426	    return matched;
427	}
