429	otError Leader::RlocLookup(uint16_t  aRloc16,
430	                           bool &    aIn,
431	                           bool &    aStable,
432	                           uint8_t * aTlvs,
433	                           uint8_t   aTlvsLength,
434	                           MatchMode aMatchMode,
435	                           bool      aAllowOtherEntries)
436	{
437	    otError            error = OT_ERROR_NONE;
438	    NetworkDataTlv *   cur   = reinterpret_cast<NetworkDataTlv *>(aTlvs);
439	    NetworkDataTlv *   end   = reinterpret_cast<NetworkDataTlv *>(aTlvs + aTlvsLength);
440	    NetworkDataTlv *   subCur;
441	    NetworkDataTlv *   subEnd;
442	    PrefixTlv *        prefix;
443	    BorderRouterTlv *  borderRouter;
444	    HasRouteTlv *      hasRoute;
445	    BorderRouterEntry *borderRouterEntry;
446	    HasRouteEntry *    hasRouteEntry;
447	#if OPENTHREAD_ENABLE_SERVICE
448	    ServiceTlv *service;
449	    ServerTlv * server;
450	#endif
451	
452	    while (cur < end)
453	    {
454	        VerifyOrExit((cur + 1) <= end && cur->GetNext() <= end, error = OT_ERROR_PARSE);
455	
456	        switch (cur->GetType())
457	        {
458	        case NetworkDataTlv::kTypePrefix:
459	        {
460	            prefix = static_cast<PrefixTlv *>(cur);
461	            VerifyOrExit(prefix->IsValid(), error = OT_ERROR_PARSE);
462	
463	            subCur = prefix->GetSubTlvs();
464	            subEnd = prefix->GetNext();
465	
466	            VerifyOrExit(subEnd <= end, error = OT_ERROR_PARSE);
467	
468	            while (subCur < subEnd)
469	            {
470	                VerifyOrExit((subCur + 1) <= subEnd && subCur->GetNext() <= subEnd, error = OT_ERROR_PARSE);
471	
472	                switch (subCur->GetType())
473	                {
474	                case NetworkDataTlv::kTypeBorderRouter:
475	                    borderRouter = static_cast<BorderRouterTlv *>(subCur);
476	
477	                    for (uint8_t i = 0; i < borderRouter->GetNumEntries(); i++)
478	                    {
479	                        borderRouterEntry = borderRouter->GetEntry(i);
480	
481	                        if (RlocMatch(borderRouterEntry->GetRloc(), aRloc16, aMatchMode))
482	                        {
483	                            aIn = true;
484	
485	                            if (borderRouter->IsStable())
486	                            {
487	                                aStable = true;
488	                            }
489	                        }
490	                        else
491	                        {
492	                            VerifyOrExit(aAllowOtherEntries, error = OT_ERROR_FAILED);
493	                        }
494	                    }
495	
496	                    break;
497	
498	                case NetworkDataTlv::kTypeHasRoute:
499	                    hasRoute = static_cast<HasRouteTlv *>(subCur);
500	
501	                    for (uint8_t i = 0; i < hasRoute->GetNumEntries(); i++)
502	                    {
503	                        hasRouteEntry = hasRoute->GetEntry(i);
504	
505	                        if (RlocMatch(hasRouteEntry->GetRloc(), aRloc16, aMatchMode))
506	                        {
507	                            aIn = true;
508	
509	                            if (hasRoute->IsStable())
510	                            {
511	                                aStable = true;
512	                            }
513	                        }
514	                        else
515	                        {
516	                            VerifyOrExit(aAllowOtherEntries, error = OT_ERROR_FAILED);
517	                        }
518	                    }
519	
520	                    break;
521	
522	                default:
523	                    break;
524	                }
525	
526	                if (aIn && aStable && aAllowOtherEntries)
527	                {
528	                    ExitNow();
529	                }
530	
531	                subCur = subCur->GetNext();
532	            }
533	        }
534	        break;
535	
536	#if OPENTHREAD_ENABLE_SERVICE
537	
538	        case NetworkDataTlv::kTypeService:
539	        {
540	            service = static_cast<ServiceTlv *>(cur);
541	            VerifyOrExit(service->IsValid(), error = OT_ERROR_PARSE);
542	
543	            subCur = service->GetSubTlvs();
544	            subEnd = service->GetNext();
545	
546	            VerifyOrExit(subEnd <= end, error = OT_ERROR_PARSE);
547	
548	            while (subCur < subEnd)
549	            {
550	                VerifyOrExit((subCur + 1) <= subEnd && subCur->GetNext() <= subEnd, error = OT_ERROR_PARSE);
551	
552	                switch (subCur->GetType())
553	                {
554	                case NetworkDataTlv::kTypeServer:
555	                    server = static_cast<ServerTlv *>(subCur);
556	                    VerifyOrExit(server->IsValid(), error = OT_ERROR_PARSE);
557	
558	                    if (RlocMatch(server->GetServer16(), aRloc16, aMatchMode))
559	                    {
560	                        aIn = true;
561	
562	                        if (server->IsStable())
563	                        {
564	                            aStable = true;
565	                        }
566	                    }
567	                    else
568	                    {
569	                        VerifyOrExit(aAllowOtherEntries, error = OT_ERROR_FAILED);
570	                    }
571	
572	                    break;
573	
574	                default:
575	                    break;
576	                }
577	
578	                if (aIn && aStable && aAllowOtherEntries)
579	                {
580	                    ExitNow();
581	                }
582	
583	                subCur = subCur->GetNext();
584	            }
585	
586	            break;
587	        }
588	
589	#endif
590	
591	        default:
592	            break;
593	        }
594	
595	        cur = cur->GetNext();
596	    }
597	
598	exit:
599	    return error;
600	}
