823	            otDumpDebgNetData("add service done", mTlvs, mLength);
824	            break;
825	#endif
826	
827	        default:
828	            break;
829	        }
830	
831	        cur = cur->GetNext();
832	    }
833	
834	    otDumpDebgNetData("add done", mTlvs, mLength);
835	
836	exit:
837	    return error;
838	}
