971	otError Leader::AddServer(ServiceTlv &aService, ServerTlv &aServer, uint8_t *aOldTlvs, uint8_t aOldTlvsLength)
972	{
973	    otError     error               = OT_ERROR_NONE;
974	    ServiceTlv *dstService          = NULL;
975	    ServiceTlv *oldService          = NULL;
976	    ServerTlv * dstServer           = NULL;
977	    uint16_t    appendLength        = 0;
978	    uint8_t     serviceID           = 0;
979	    uint8_t     serviceInsertLength = sizeof(ServiceTlv) + sizeof(uint8_t) /*mServiceDataLength*/ +
980	                                  ServiceTlv::GetEnterpriseNumberFieldLength(aService.GetEnterpriseNumber()) +
981	                                  aService.GetServiceDataLength();
982	
983	    dstService =
984	        FindService(aService.GetEnterpriseNumber(), aService.GetServiceData(), aService.GetServiceDataLength());
985	
986	    if (dstService == NULL)
987	    {
988	        appendLength += serviceInsertLength;
989	    }
990	
991	    appendLength += sizeof(ServerTlv) + aServer.GetServerDataLength();
992	
993	    VerifyOrExit(mLength + appendLength <= sizeof(mTlvs), error = OT_ERROR_NO_BUFS);
994	
995	    if (dstService == NULL)
996	    {
997	        // Try to preserve old Service ID, if existing
998	        oldService = FindService(aService.GetEnterpriseNumber(), aService.GetServiceData(),
999	                                 aService.GetServiceDataLength(), aOldTlvs, aOldTlvsLength);
1000	
1001	        if (oldService != NULL)
1002	        {
1003	            // The same service is not found in current data, but was in old data. So, it had to be just removed by
1004	            // RemoveRloc() Lets use the same ServiceID
1005	            serviceID = oldService->GetServiceID();
1006	        }
1007	        else
1008	        {
1009	            uint8_t i;
1010	
1011	            // This seems like completely new service. Lets try to find new ServiceID for it. If all are taken, error
1012	            // out. Since we call FindServiceById() on mTlv, we need to execute this before Insert() call, otherwise
1013	            // we'll find uninitialized service as well.
1014	            for (i = Mle::kServiceMinId; i <= Mle::kServiceMaxId; i++)
1015	            {
1016	                if (FindServiceById(i) == NULL)
1017	                {
1018	                    serviceID = i;
1019	                    break;
1020	                }
1021	            }
1022	
1023	            otLogInfoNetData("Allocated Service ID = %d", i);
1024	
1025	            VerifyOrExit(i <= Mle::kServiceMaxId, error = OT_ERROR_NO_BUFS);
1026	        }
1027	
1028	        dstService = reinterpret_cast<ServiceTlv *>(mTlvs + mLength);
1029	        Insert(reinterpret_cast<uint8_t *>(dstService), serviceInsertLength);
1030	        dstService->Init();
1031	        dstService->SetServiceID(serviceID);
1032	        dstService->SetEnterpriseNumber(aService.GetEnterpriseNumber());
1033	        dstService->SetServiceData(aService.GetServiceData(), aService.GetServiceDataLength());
1034	        dstService->SetLength(serviceInsertLength - sizeof(NetworkDataTlv));
1035	    }
1036	
1037	    dstServer = static_cast<ServerTlv *>(dstService->GetNext());
1038	
1039	    Insert(reinterpret_cast<uint8_t *>(dstServer), sizeof(ServerTlv) + aServer.GetServerDataLength());
1040	    dstServer->Init();
1041	    dstServer->SetServer16(aServer.GetServer16());
1042	    dstServer->SetServerData(aServer.GetServerData(), aServer.GetServerDataLength());
1043	
1044	    if (aServer.IsStable())
1045	    {
1046	        dstService->SetStable();
1047	        dstServer->SetStable();
1048	    }
1049	
1050	    dstService->SetLength(dstService->GetLength() + sizeof(ServerTlv) + aServer.GetServerDataLength());
1051	
1052	exit:
1053	    return error;
1054	}
