1236	void Leader::RemoveRloc(uint16_t aRloc16, MatchMode aMatchMode)
1237	{
1238	    NetworkDataTlv *cur = reinterpret_cast<NetworkDataTlv *>(mTlvs);
1239	    NetworkDataTlv *end;
1240	    PrefixTlv *     prefix;
1241	#if OPENTHREAD_ENABLE_SERVICE
1242	    ServiceTlv *service;
1243	#endif
1244	
1245	    while (1)
1246	    {
1247	        end = reinterpret_cast<NetworkDataTlv *>(mTlvs + mLength);
1248	
1249	        if (cur >= end)
1250	        {
1251	            break;
1252	        }
1253	
1254	        switch (cur->GetType())
1255	        {
1256	        case NetworkDataTlv::kTypePrefix:
1257	        {
1258	            prefix = static_cast<PrefixTlv *>(cur);
1259	            RemoveRloc(*prefix, aRloc16, aMatchMode);
1260	
1261	            if (prefix->GetSubTlvsLength() == 0)
1262	            {
1263	                Remove(reinterpret_cast<uint8_t *>(prefix), sizeof(NetworkDataTlv) + prefix->GetLength());
1264	                continue;
1265	            }
1266	
1267	            otDumpDebgNetData("remove prefix done", mTlvs, mLength);
1268	            break;
1269	        }
1270	
1271	#if OPENTHREAD_ENABLE_SERVICE
1272	
1273	        case NetworkDataTlv::kTypeService:
1274	        {
1275	            service = static_cast<ServiceTlv *>(cur);
1276	            RemoveRloc(*service, aRloc16, aMatchMode);
1277	
1278	            if (service->GetSubTlvsLength() == 0)
1279	            {
1280	                Remove(reinterpret_cast<uint8_t *>(service), sizeof(NetworkDataTlv) + service->GetLength());
1281	                continue;
1282	            }
1283	
1284	            otDumpDebgNetData("remove service done", mTlvs, mLength);
1285	
1286	            break;
1287	        }
1288	
1289	#endif
1290	
1291	        default:
1292	            break;
1293	        }
1294	
1295	        cur = cur->GetNext();
1296	    }
1297	
1298	    otDumpDebgNetData("remove done", mTlvs, mLength);
1299	}
