1301	void Leader::RemoveRloc(PrefixTlv &aPrefix, uint16_t aRloc16, MatchMode aMatchMode)
1302	{
1303	    NetworkDataTlv *cur = aPrefix.GetSubTlvs();
1304	    NetworkDataTlv *end;
1305	    ContextTlv *    context;
1306	
1307	    while (1)
1308	    {
1309	        end = aPrefix.GetNext();
1310	
1311	        if (cur >= end)
1312	        {
1313	            break;
1314	        }
1315	
1316	        switch (cur->GetType())
1317	        {
1318	        case NetworkDataTlv::kTypeHasRoute:
1319	            RemoveRloc(aPrefix, *static_cast<HasRouteTlv *>(cur), aRloc16, aMatchMode);
1320	
1321	            // remove has route tlv if empty
1322	            if (cur->GetLength() == 0)
1323	            {
1324	                aPrefix.SetSubTlvsLength(aPrefix.GetSubTlvsLength() - sizeof(HasRouteTlv));
1325	                Remove(reinterpret_cast<uint8_t *>(cur), sizeof(HasRouteTlv));
1326	                continue;
1327	            }
1328	
1329	            break;
1330	
1331	        case NetworkDataTlv::kTypeBorderRouter:
1332	            RemoveRloc(aPrefix, *static_cast<BorderRouterTlv *>(cur), aRloc16, aMatchMode);
1333	
1334	            // remove border router tlv if empty
1335	            if (cur->GetLength() == 0)
1336	            {
1337	                aPrefix.SetSubTlvsLength(aPrefix.GetSubTlvsLength() - sizeof(BorderRouterTlv));
1338	                Remove(reinterpret_cast<uint8_t *>(cur), sizeof(BorderRouterTlv));
1339	                continue;
1340	            }
1341	
1342	            break;
1343	
1344	        default:
1345	            break;
1346	        }
1347	
1348	        cur = cur->GetNext();
1349	    }
1350	
1351	    if ((context = FindContext(aPrefix)) != NULL)
1352	    {
1353	        if (aPrefix.GetSubTlvsLength() == sizeof(ContextTlv))
1354	        {
1355	            context->ClearCompress();
1356	            StartContextReuseTimer(context->GetContextId());
1357	        }
1358	        else
1359	        {
1360	            context->SetCompress();
1361	            StopContextReuseTimer(context->GetContextId());
1362	        }
1363	    }
1364	}
