1527	void Leader::UpdateContextsAfterReset(void)
1528	{
1529	    PrefixTlv * prefix;
1530	    ContextTlv *contextTlv;
1531	
1532	    // Iterate through Network Data and synchronize missing contexts.
1533	    for (NetworkDataTlv *cur                                            = reinterpret_cast<NetworkDataTlv *>(mTlvs);
1534	         cur < reinterpret_cast<NetworkDataTlv *>(mTlvs + mLength); cur = cur->GetNext())
1535	    {
1536	        if (cur->GetType() != NetworkDataTlv::kTypePrefix)
1537	        {
1538	            continue;
1539	        }
1540	
1541	        prefix     = static_cast<PrefixTlv *>(cur);
1542	        contextTlv = FindContext(*prefix);
1543	
1544	        if (contextTlv == NULL)
1545	        {
1546	            continue;
1547	        }
1548	
1549	        mContextUsed |= 1 << contextTlv->GetContextId();
1550	
1551	        if (contextTlv->IsCompress())
1552	        {
1553	            StopContextReuseTimer(contextTlv->GetContextId());
1554	        }
1555	        else
1556	        {
1557	            StartContextReuseTimer(contextTlv->GetContextId());
1558	        }
