1567	void Leader::HandleTimer(void)
1568	{
1569	    bool contextsWaiting = false;
1570	
1571	    for (uint8_t i = 0; i < kNumContextIds; i++)
1572	    {
1573	        if (mContextLastUsed[i] == 0)
1574	        {
1575	            continue;
1576	        }
1577	
1578	        if ((TimerMilli::GetNow() - mContextLastUsed[i]) >= TimerMilli::SecToMsec(mContextIdReuseDelay))
1579	        {
1580	            FreeContext(kMinContextId + i);
1581	        }
1582	        else
1583	        {
1584	            contextsWaiting = true;
1585	        }
1586	    }
1587	
1588	    if (contextsWaiting)
1589	    {
1590	        mTimer.Start(kStateUpdatePeriod);
1591	    }
